import {TYPES,STEPS,LIMITS,blank,node,edge,group,uid,copy,clamp,esc,validate,loadProject,removeItems,analyze,trace,simulate,bounds,geometry,duplicate,fromCollaboration} from './systems/model.js';
import {TEMPLATES,template} from './systems/templates.js';
import {svg,report,csv,png,collaboration,participantCSV,download,safeName} from './systems/exports.js';
import {rpc,readLocal,saveLocal,deleteLocal,getLocal} from './systems/storage.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const participant=document.body.dataset.entry==='participant';
const S={project:blank(),version:0,dirty:false,rev:0,selected:new Set(),tool:'select',tab:'inspect',view:{x:45,y:65,z:.8},history:[],future:[],highlight:null,trace:null,session:null,member:null,conflict:false,saving:false,gesture:null,space:false,clip:[],closing:false};
let toastTimer,localTimer,cloudTimer,pollTimer,lastAnalysis=-1,analysisCache,modalReturn,focusSnapshot=null;
const editable=()=>!participant||!!S.member&&S.session?.mode==='edit'&&!S.session?.locked&&S.session?.active!==false;
const status=x=>{$('#save-status').textContent=x;};
function toast(x){$('#toast').textContent=x;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),5000);}
function snapshot(){S.history.push(copy(S.project));if(S.history.length>45)S.history.shift();S.future=[];updateUndo();}
function updateUndo(){$('#undo').disabled=!editable()||!S.history.length||!!S.session;$('#redo').disabled=!editable()||!S.future.length||!!S.session;}
function changed({cloud=true}={}){
 S.rev++;S.dirty=true;S.project.updatedAt=new Date().toISOString();lastAnalysis=-1;
 clearTimeout(localTimer);localTimer=setTimeout(()=>{if(!saveLocal(S.project,S.version,true))status('Device storage full · export a backup');else status(S.conflict?'Save conflict · device draft kept':S.version?'Device draft saved · website pending':'Saved on this device · select Save for website');},120);
 clearTimeout(cloudTimer);if(cloud&&(S.version||participant)&&!S.conflict)cloudTimer=setTimeout(()=>save(),1400);
}
function transact(fn){if(!editable()){toast('The facilitator has made this map read-only.');return;}snapshot();fn();S.highlight=null;S.trace=null;changed();render();}
function flushLocal(){clearTimeout(localTimer);return S.project.nodes.length||S.dirty||S.version?saveLocal(S.project,S.version,S.dirty):true;}
function canSwitch(){if(!flushLocal()&&S.dirty){toast('Device storage is full. Save to the website or export a JSON backup before switching maps.');return false;}return !S.saving||confirm('A website save is still running. A device copy is kept. Open another map now?');}
function openProject(p,version=0,dirty=false){if(!canSwitch())return;clearTimeout(cloudTimer);S.project=loadProject(p);S.version=version;S.dirty=dirty;S.conflict=false;S.selected.clear();S.history=[];S.future=[];S.highlight=null;S.trace=null;S.session=null;S.rev++;lastAnalysis=-1;render();fit();status(dirty?'Recovered device draft · website save pending':version?'Website version '+version:'Device project');renderSession();}
function getAnalysis(){if(lastAnalysis!==S.rev){analysisCache=analyze(S.project);lastAnalysis=S.rev;}return analysisCache;}
function current(){const id=[...S.selected][0];return S.project.nodes.find(x=>x.id===id)||S.project.edges.find(x=>x.id===id)||S.project.groups.find(x=>x.id===id);}
function select(id,add=false){if(!add)S.selected.clear();if(id){if(add&&S.selected.has(id))S.selected.delete(id);else S.selected.add(id);}paintSelection();renderInspector();}
function paintSelection(){$$('.map-node,.map-group').forEach(el=>{el.classList.toggle('selected',S.selected.has(el.dataset.id));el.classList.toggle('highlight',!!S.highlight?.nodes.includes(el.dataset.id));el.classList.toggle('dim',!!S.highlight&&!S.highlight.nodes.includes(el.dataset.id));});renderEdges();}
function setTool(t){S.tool=t;$$('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===t));$('#viewport').classList.toggle('connect-mode',t==='connect');S.connectFrom=null;$('#connect-preview').hidden=true;$('#canvas-tip').textContent=t==='connect'?'Click a cause, then an effect.':t==='pan'?'Drag anywhere to pan.':'Drag headers to move. Click text to edit.';}
function view(){const v=S.view;$('#world').style.transform=`translate(${v.x}px,${v.y}px) scale(${v.z})`;$('#zoom-label').textContent=Math.round(v.z*100)+'%';$('#viewport').style.backgroundSize=(22*v.z)+'px '+(22*v.z)+'px';$('#viewport').style.backgroundPosition=v.x+'px '+v.y+'px';renderMinimap();}
function viewportSize(){const r=$('#viewport').getBoundingClientRect();return {w:r.width||900,h:r.height||650};}
function worldPoint(e){const r=$('#viewport').getBoundingClientRect();return {x:(e.clientX-r.left-S.view.x)/S.view.z,y:(e.clientY-r.top-S.view.y)/S.view.z};}
function center(){const r=viewportSize();return {x:(r.w/2-S.view.x)/S.view.z-100,y:(r.h/2-S.view.y)/S.view.z-56};}
function fit(){const b=bounds(S.project),s=viewportSize();S.view.z=clamp(Math.min((s.w-90)/b.w,(s.h-90)/b.h),.15,1.3);S.view.x=(s.w-b.w*S.view.z)/2-b.x*S.view.z;S.view.y=(s.h-b.h*S.view.z)/2-b.y*S.view.z;view();}
function zoom(factor,anchor){const s=viewportSize(),x=anchor?.x??s.w/2,y=anchor?.y??s.h/2,z=clamp(S.view.z*factor,.15,2.5),r=z/S.view.z;S.view.x=x-(x-S.view.x)*r;S.view.y=y-(y-S.view.y)*r;S.view.z=z;view();}
function renderMinimap(){const b=bounds(S.project),s=viewportSize(),v=S.view;$('#map-minimap').innerHTML=`<svg viewBox="${b.x} ${b.y} ${b.w} ${b.h}" aria-label="Map overview">${S.project.nodes.map(n=>`<rect x="${n.x}" y="${n.y}" width="${n.w}" height="${n.h}" rx="8" fill="${n.color}" stroke="#7499b5" stroke-width="5"/>`).join('')}<rect x="${-v.x/v.z}" y="${-v.y/v.z}" width="${s.w/v.z}" height="${s.h/v.z}" fill="none" stroke="#c79531" stroke-width="7"/></svg>`;}
function renderEdges(){const p=S.project;$('#edge-layer').innerHTML=p.edges.map(e=>{const q=geometry(p,e);if(!q)return '';const selected=S.selected.has(e.id),highlight=S.highlight?.edges.includes(e.id),color=selected||highlight?'#bf8a24':e.kind==='flow'?'#25856e':'#527e9f';return `<g data-edge="${e.id}" style="opacity:${S.highlight&&!highlight?.valueOf()?'.3':'1'}"><path class="edge-hit" d="${q.d}"/><path d="${q.d}" fill="none" stroke="${color}" stroke-width="${highlight?5:e.strength==='strong'?4:2.5}" ${e.delayed?'stroke-dasharray="9 5"':''} marker-end="url(#${selected||highlight?'arrow-selected':'arrow'})"/><rect class="edge-label" x="${q.x-17}" y="${q.y-14}" width="34" height="28" rx="12"/><text x="${q.x}" y="${q.y+5}" text-anchor="middle" font-size="18" font-weight="bold" fill="${color}">${e.kind==='causal'?esc(e.polarity):e.kind==='flow'?'⇢':'i'}</text>${e.delayed?`<text x="${q.x+24}" y="${q.y+5}" font-size="17" fill="#956a1e">||</text>`:''}${e.label?`<text x="${q.x}" y="${q.y+31}" font-size="11" text-anchor="middle" fill="#3e657f">${esc(e.label.slice(0,55))}</text>`:''}</g>`;}).join('');}
function renderNodes(){
 $('#groups').innerHTML=S.project.groups.map(g=>`<div class="map-group" data-id="${g.id}" style="left:${g.x}px;top:${g.y}px;width:${g.w}px;height:${g.h}px;background:${g.color}33"><div class="group-label">${esc(g.label)}</div><button class="resize-handle" aria-label="Resize boundary"></button></div>`).join('');
 $('#nodes').innerHTML=S.project.nodes.map(n=>`<div class="map-node" data-id="${n.id}" data-type="${n.type}" style="left:${n.x}px;top:${n.y}px;width:${n.w}px;height:${n.h}px;background:${n.color}"><div class="node-header"><span>${esc(TYPES[n.type][1])}</span><span>${n.leverage?'✦ ':''}${n.locked?'▣':''}</span></div><div class="node-label" role="textbox" aria-label="${esc(TYPES[n.type][1])} text" contenteditable="${editable()&&!n.locked?'true':'false'}" spellcheck="true">${esc(n.label)}</div><button class="port" aria-label="Connect ${esc(n.label)} to another element" title="Drag to an effect, or click two elements in Connect mode"></button><button class="resize-handle" aria-label="Resize ${esc(n.label)}"></button></div>`).join('');
 $('#empty-hint').hidden=S.project.nodes.length>0;$('#item-count').textContent=`${S.project.nodes.length} elements · ${S.project.edges.length} relationships`;
 paintSelection();renderMinimap();
}
const field=(label,key,value,type='text',options=null)=>`<label class="field">${esc(label)}${options?`<select data-field="${key}">${options.map(o=>`<option value="${esc(Array.isArray(o)?o[0]:o)}" ${value===(Array.isArray(o)?o[0]:o)?'selected':''}>${esc(Array.isArray(o)?o[1]:o)}</option>`).join('')}</select>`:type==='textarea'?`<textarea data-field="${key}" maxlength="8000">${esc(value)}</textarea>`:`<input type="${type}" data-field="${key}" value="${esc(value)}" ${type==='number'?'step="any"':''}>`}</label>`;
function renderGuide(){$('#guide').hidden=S.project.mode!=='guided';$$('[data-mode]').forEach(b=>b.classList.toggle('active',b.dataset.mode===S.project.mode));const step=STEPS[S.project.stage];$('#guide-counter').textContent=`Step ${S.project.stage+1} of 8`;$('#guide-name').textContent=step[0];$('#guide-description').textContent=step[1];$('#guide-prev').disabled=S.project.stage===0;$('#guide-next').disabled=S.project.stage===7;}
function renderInspector(){
 $$('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===S.tab));const p=S.project,a=getAnalysis(),item=current();let content='';
 if(S.tab==='loops'){
  content=`<div class="metric-row">${['reinforcing','balancing','uncertain'].map(t=>`<div class="metric"><strong>${a.counts[t]}</strong>${t}</div>`).join('')}</div><p class="hint">Even negative links = reinforcing. Odd = balancing. Unknown signs leave a loop uncertain. Delays affect timing, not polarity.</p>${a.truncated||a.depthLimited?'<div class="warning">Analysis limit reached; this loop list may be incomplete.</div>':''}<div class="button-row"><button data-action="clear-highlight">Show whole map</button></div>`;
  if(!a.loops.length)content+='<div class="card">No closed causal loops yet. Connect an effect back to an earlier cause. Flow and information links are excluded.</div>';
  a.loops.forEach((l,i)=>{content+=`<div class="loop-card"><strong class="badge ${l.type}">${l.type==='reinforcing'?'R':l.type==='balancing'?'B':'?'}${i+1} · ${l.type}</strong><p>${esc(l.nodes.map(id=>p.nodes.find(n=>n.id===id)?.label).join(' → '))} ↻</p><p>${l.negative} negative link(s) · ${l.delays} delay(s)</p><button data-loop="${i}">Highlight this loop</button></div>`;});
 }else if(S.tab==='review'){
  content=`<h3>Map quality review</h3><p class="hint">Use these prompts to improve your working hypothesis.</p>${a.review.length?a.review.map(x=>`<div class="review-card hint">${esc(x)}</div>`).join(''):'<div class="card">No structural warnings. Review the causal claims with your stakeholders.</div>'}<h3>Connectivity prompts</h3><p class="hint">High outgoing connectivity suggests a place to investigate. It does not prove an effective leverage point.</p>`;
  content+=a.ranking.slice(0,10).map(r=>`<div class="card"><strong>${esc(r.label)}</strong><p class="hint">${r.outgoing} outgoing · ${r.incoming} incoming · ${r.loops} detected loops</p><button data-select-node="${r.id}">Inspect intervention</button></div>`).join('');
 }else if(item&&S.selected.size===1){
  const isNode=p.nodes.includes(item),isEdge=p.edges.includes(item),isGroup=p.groups.includes(item);
  if(isEdge){content=`<h3>Influence relationship</h3><p class="hint">${esc(p.nodes.find(n=>n.id===item.from)?.label)} → ${esc(p.nodes.find(n=>n.id===item.to)?.label)}</p>${field('Relationship type','kind',item.kind,'text',[['causal','Causal influence'],['flow','Stock / flow'],['information','Information']])}${field('Polarity','polarity',item.polarity,'text',[['+','+ Same direction'],['-','− Opposite direction'],['?','? Unknown / conditional']])}${field('Label','label',item.label)}${field('Strength (qualitative)','strength',item.strength,'text',['weak','medium','strong'])}${field('Confidence','confidence',item.confidence,'text',['hypothesis','observed','supported'])}${field('Supporting evidence / conditions','evidence',item.evidence,'textarea')}<label class="check"><input type="checkbox" data-field="delayed" ${item.delayed?'checked':''}> Has a time delay</label>${field('Delay estimate and unit','delay',item.delay)}${field('Curve offset','bend',item.bend,'number')}<div class="button-row"><button data-action="reverse-edge">⇄ Reverse direction</button></div>`;
  }else{content=`<h3>${isGroup?'System boundary':esc(TYPES[item.type][1])}</h3>${field('Label','label',item.label)}${isNode?field('Element type','type',item.type,'text',Object.entries(TYPES).map(([k,v])=>[k,v[1]])):''}${field('Notes / meaning','notes',item.notes,'textarea')}${field('Color','color',item.color,'color')}<div class="two-fields">${field('Width','w',item.w,'number')}${field('Height','h',item.h,'number')}</div><label class="check"><input type="checkbox" data-field="locked" ${item.locked?'checked':''}> Lock position and text</label>`;
   if(isNode)content+=`${field('Subsystem / boundary','group',item.group,'text',[['','None'],...p.groups.map(g=>[g.id,g.label])])}${field('Confidence','confidence',item.confidence,'text',['hypothesis','observed','supported'])}${field('Evidence','evidence',item.evidence,'textarea')}${field('Unit (if applicable)','unit',item.unit)}${item.type==='stock'?field('Initial amount','initial',item.initial,'number'):''}${item.type==='flow'?field('Constant rate per time unit','rate',item.rate,'number'):''}<label class="check"><input type="checkbox" data-field="leverage" ${item.leverage?'checked':''}> Mark as a potential leverage point</label><div class="button-row"><button data-action="trace-up">Trace an increase</button><button data-action="trace-down">Trace a decrease</button><button data-action="duplicate">Duplicate</button></div>`;
  }content+='<button class="danger full" data-action="delete">Delete selected</button>';
  if(S.trace){content+='<h3>Possible consequences</h3><p class="hint">Qualitative paths, up to 3 links. Multiple paths can conflict. This does not predict actual net change.</p>'+S.trace.paths.map(path=>`<div class="card hint">${path.depth}${path.depth===1?'st':path.depth===2?'nd':'rd'} order · ${esc(p.nodes.find(n=>n.id===path.nodes.at(-1))?.label)}: ${path.sign===1?'same direction as the original increase':path.sign===-1?'opposite direction to the original increase':'unknown'}<br>${esc(path.nodes.map(id=>p.nodes.find(n=>n.id===id)?.label).join(' → '))}${path.delays?' · delayed':''}</div>`).join('');}
 }else{
  content=`<h3>${S.selected.size>1?S.selected.size+' items selected':'Frame your system'}</h3>${S.selected.size>1?'<div class="button-row"><button data-action="duplicate">Duplicate</button><button data-action="align">Align top</button><button data-action="delete" class="danger">Delete selected</button></div>':''}<p class="hint">Click text to type directly. Drag a header to move an element; use the gold corner to resize. Select an arrow to edit its polarity and delay.</p>${field('Focal issue','issue',p.issue,'textarea')}${field('Desired outcome','purpose',p.purpose,'textarea')}${field('What is in / out of scope?','boundary',p.boundary,'textarea')}${field('Time horizon','timeHorizon',p.timeHorizon)}${field('Folder','folder',p.folder)}${field('Tags (comma separated)','tags',p.tags)}<button data-action="history" class="full owner-only">Version history</button><label class="check"><input id="auto-save" type="checkbox" checked disabled> Website autosave after first Save</label>`;
 }$('#inspector').innerHTML=content;
 if(!editable())$('#inspector').querySelectorAll('input,select,textarea').forEach(x=>x.disabled=true);
 updateUndo();
}
function render(){$('#project-title').value=S.project.title;document.body.classList.toggle('read-only',!editable());renderGuide();renderNodes();renderInspector();view();}
function addNode(type,point=center()){if(S.project.nodes.length>=LIMITS.nodes)return toast('This map supports up to 250 elements.');transact(()=>{const n=node(type,Math.round(point.x/10)*10,Math.round(point.y/10)*10);S.project.nodes.push(n);S.selected=new Set([n.id]);});}
function connect(from,to){if(S.project.edges.length>=LIMITS.edges)return toast('This map supports up to 600 relationships.');if(S.project.edges.some(e=>e.from===from&&e.to===to&&e.kind==='causal'))return toast('That causal relationship exists. Select its arrow to edit it.');transact(()=>{const e=edge(from,to);S.project.edges.push(e);S.selected=new Set([e.id]);});S.connectFrom=null;}
function show(title,html){modalReturn=document.activeElement;$('#modal-title').textContent=title;$('#modal-content').innerHTML=html;$('#modal-backdrop').hidden=false;$('#close-modal').focus();}
function closeModal(){$('#modal-backdrop').hidden=true;modalReturn?.focus?.();}
function reset(){if(!editable())return;if(!canSwitch())return;openProject(blank());status('New blank map');}
async function save(){
 if(S.saving||S.conflict)return;if(!editable())return toast('This classroom map is read-only.');
 clearTimeout(cloudTimer);const issues=validate(S.project);if(issues.length)return toast(issues[0]);
 const p=copy(S.project),id=p.id,rev=S.rev,version=S.version;flushLocal();S.saving=true;status('Saving to website…');
 try{const d=await rpc(participant?'session-save':'save',participant?{room:S.session.room,member:S.member.id,proof:S.member.proof,id,version,data:p}:{id,version,data:p});
  if(S.project.id===id){S.version=d.version;S.dirty=S.rev!==rev;saveLocal(S.project,S.version,S.dirty);status(S.dirty?'New device edits · syncing next':'Saved to website · version '+d.version);if(S.dirty)cloudTimer=setTimeout(()=>save(),300);}
 }catch(e){if(S.project.id===id){if(e.status===409){S.conflict=true;status('Version conflict · device draft retained');renderSession();toast('Another participant saved first. Your changes are kept on this device. Export your draft, then use Reload website version.');}else{status('Website save failed · device draft kept');toast(e.message);}}}
 finally{S.saving=false;}
}
async function library(){
 show('My Maps','<p>Loading website projects… Device copies are also retained.</p>');let remote=[],message='';try{remote=await rpc('list');}catch(e){message=e.message;}
 const local=readLocal(),map=new Map(remote.map(x=>[x.id,{...x,remote:true}]));for(const [id,x] of Object.entries(local)){const other=map.get(id);if(!other||x.dirty)map.set(id,{id,title:x.data.title,folder:x.data.folder,tags:x.data.tags,version:x.version,updated_at:x.updated_at,remote:!!other,local:true,dirty:x.dirty});else map.set(id,{...other,local:true});}
 const items=[...map.values()].sort((a,b)=>String(b.updated_at).localeCompare(String(a.updated_at)));
 $('#modal-content').innerHTML=`<div class="library-bar"><input type="text" id="library-search" placeholder="Search names, folders, or tags" aria-label="Search maps"><button data-action="import">Import project</button></div>${message?`<p class="warning">${esc(message)}</p>`:''}<p class="hint">Projects are shared with instructors who have the website PIN. Device drafts remain available if website saving fails.</p><div class="library-list" id="library-results"></div>`;
 const draw=()=>{const q=$('#library-search').value.toLowerCase();$('#library-results').innerHTML=items.filter(x=>[x.title,x.folder,x.tags].join(' ').toLowerCase().includes(q)).map(x=>`<div class="card"><span class="eyebrow">${esc(x.folder||'MY MAPS')}</span><h3>${esc(x.title)}</h3><p>${x.dirty?'Unsynced device draft':x.remote?'Website · v'+x.version:'This device'} · ${esc(String(x.updated_at).slice(0,10))}</p><div class="button-row"><button data-open-map="${x.id}" data-source="${x.dirty||!x.remote?'local':'remote'}">Open</button><button data-copy-map="${x.id}" data-source="${x.dirty||!x.remote?'local':'remote'}">Duplicate</button>${x.remote?`<button data-archive-map="${x.id}" class="danger">Archive website</button>`:''}${x.local?`<button data-remove-local="${x.id}">Remove device copy</button>`:''}</div></div>`).join('')||'<p>No maps found. Create a map and select Save.</p>';};$('#library-search').addEventListener('input',draw);draw();
}
async function getSource(id,source){return source==='local'?getLocal(id):rpc('get',{id});}
function exportMenu(){show('Export your map',`<div class="export-options">${[['json','Editable project JSON','Reopen the complete map in this studio.'],['svg','Vector map SVG','Scalable image of your entire canvas.'],['png','Map image PNG','High-resolution image; capped at 6000 pixels.'],['pdf','PDF map & analysis report','Download a vector map and a multi-page report.'],['report','HTML report / Print','Map, loops, evidence, actions and reflection.'],['csv','Elements & relationships CSV','Open your map data in Excel.'],['collaboration','Collaboration Canvas JSON','Transfer the layout to Collaboration Canvas.']].map(([id,title,detail])=>`<button data-export="${id}"><strong>${title}</strong><p class="hint">${detail}</p></button>`).join('')}</div><p class="hint">Exported reports are self-contained. JSON retains source data; Collaboration Canvas transfer retains layout and text and does not carry systems analysis metadata.</p>`);}
async function doExport(kind){const p=S.project,name=safeName(p);try{if(kind==='json')download(name+'.systems.json',JSON.stringify(p,null,2));if(kind==='svg')download(name+'.svg',svg(p),'image/svg+xml');if(kind==='png')download(name+'.png',await png(p),'image/png');if(kind==='pdf'){const {pdfReport}=await import('/assets/systems-pdf.js');download(name+'-report.pdf',new Blob([await pdfReport(p)],{type:'application/pdf'}));}if(kind==='report')download(name+'-report.html',report(p),'text/html');if(kind==='csv')download(name+'.csv',csv(p),'text/csv;charset=utf-8');if(kind==='collaboration')download(name+'-canvas.json',JSON.stringify(collaboration(p),null,2));toast('Export created.');}catch(e){toast(e.message);}}
function worksheet(type){
 if(type==='iceberg')show('Iceberg exploration',`<p class="hint">Move from visible events toward structures and beliefs that sustain them.</p><div class="worksheet-grid">${[['events','Events · What happened?'],['patterns','Patterns · What keeps recurring?'],['structures','Structures · What produces the pattern?'],['mentalModels','Mental models · What beliefs sustain it?']].map(([k,label])=>field(label,'iceberg.'+k,S.project.iceberg[k],'textarea')).join('')}</div>`);
 if(type==='behavior'){
  show('Behavior over time',`<p class="hint">Enter observed or hypothesized values in time order, separated by commas. This chart describes a pattern; it does not simulate causal-loop behavior.</p>${field('Series name','behavior.label',S.project.behavior.label)}${field('Unit','behavior.unit',S.project.behavior.unit)}${field('Values in time order','behavior.points',S.project.behavior.points)}<div id="behavior-chart" class="chart"></div>${field('Interpret the pattern and identify the source','behavior.interpretation',S.project.behavior.interpretation,'textarea')}`);drawBehavior();
 }
 if(type==='simulation'){
  const sim=simulate(S.project);show('Stock & flow illustration',`<p class="warning">Constant-rate illustration only. Set initial quantities on Stock elements and rates on Flow elements. Connect Stock → Flow → Stock using the Stock / flow relationship type. Units must be consistent. Causal arrows do not drive this calculation. Negative amounts are allowed and need interpretation.</p>${sim.stocks.length?'<div class="chart">'+lineChart(sim.stocks.map(n=>({name:n.label,values:sim.rows.map(r=>r[n.id])})))+'</div>'+`<p>20 time steps, Δt = 1 time unit.</p><button data-action="simulation-csv">Download calculation CSV</button>`:'<p>Add a Stock and Flow or load the Stock and Flow template.</p>'}`);
 }
 if(type==='actions'){show('Interventions & action plan',`${field('Recommendation and intervention hypothesis','recommendation',S.project.recommendation,'textarea')}<p class="hint">Choose a small test, name an owner, and define what you will observe.</p><div id="action-list"></div><button data-action="add-action">+ Add action</button>${field('Reflection · What changed in your understanding?','reflection',S.project.reflection,'textarea')}`);drawActions();}
 if(!editable())$('#modal-content').querySelectorAll('input,textarea,select').forEach(x=>x.disabled=true);
}
function lineChart(series){const values=series.flatMap(s=>s.values).filter(Number.isFinite);if(!values.length)return '<p class="hint">Add numeric values to draw a chart.</p>';let min=Math.min(...values),max=Math.max(...values);if(max===min){min-=1;max+=1;}const colors=['#286da1','#bb872b','#2e8b70','#a06ba7'];return `<svg viewBox="0 0 620 230" aria-label="Behavior over time"><path d="M45 15V195H600" fill="none" stroke="#a0b7c9"/><text x="2" y="25" font-size="11">${max.toFixed(1)}</text><text x="2" y="195" font-size="11">${min.toFixed(1)}</text>${series.map((s,i)=>`<polyline fill="none" stroke="${colors[i%4]}" stroke-width="3" points="${s.values.map((n,j)=>`${45+j*550/Math.max(1,s.values.length-1)},${190-(n-min)/(max-min)*165}`).join(' ')}"/><text x="${50+(i%3)*185}" y="${214+Math.floor(i/3)*12}" fill="${colors[i%4]}" font-size="11">${esc(s.name.slice(0,25))}</text>`).join('')}</svg>`;}
function drawBehavior(){const vals=S.project.behavior.points.split(/[,\n]+/).map(x=>x.trim()).filter(Boolean).slice(0,100);$('#behavior-chart').innerHTML=vals.some(x=>!Number.isFinite(Number(x)))?'<p>Use numeric values separated by commas.</p>':lineChart([{name:S.project.behavior.label||'Pattern',values:vals.map(Number)}]);}
function drawActions(){$('#action-list').innerHTML=S.project.actions.map(a=>`<div class="action-row" data-action-id="${a.id}">${field('Action','action.text',a.text,'textarea')}${field('Owner','action.owner',a.owner)}${field('Due','action.due',a.due,'date')}${field('Success measure','action.measure',a.measure)}${field('Status','action.status',a.status,'text',['planned','in progress','complete'])}<button data-remove-action="${a.id}">Remove action</button></div>`).join('');}
function inviteLink(){return location.origin+'/systems-mapping-join.html#room='+S.session.room;}
function renderSession(){
 const s=S.session;$('#session-strip').innerHTML=s?`<strong>${participant?'Classroom map':'Hosting classroom'} · ${s.locked?'Locked':s.mode==='view'?'View only':'Editing open'}</strong><span id="session-timer"></span>${participant?'<button data-action="student-reflect">Submit reflection</button>':'<button data-action="classroom">Session controls</button>'}<button data-action="reload-cloud">Reload website version</button>`:S.conflict?'<span>Another save arrived first. Your draft is retained.</span><button data-action="reload-cloud">Reload website version</button>':'';
 document.body.classList.toggle('read-only',!editable());document.body.classList.toggle('has-session',!!$('#session-strip').innerHTML);updateTimer();updateUndo();
}
function updateTimer(){const el=$('#session-timer');if(!el)return;const deadline=S.session?.deadline;if(!deadline){el.textContent='';return;}const left=Math.max(0,Math.ceil((new Date(deadline).getTime()-Date.now())/1000));el.textContent=left?`${Math.floor(left/60)}:${String(left%60).padStart(2,'0')} remaining`:'Time complete';}
async function classroom(){
 if(participant)return;
 if(!S.session){show('Start a classroom session',`<p>Invite students to collaborate on this map through a public student link. They do not need the instructor PIN. Everyone with that link can join, so share it with your class.</p><p class="hint">Save your map first. Each session supports up to 60 participants. Saves use revision checks to prevent silent overwrites; conflicting drafts are retained for review.</p><button data-action="host-session" class="primary">Save & start session</button>`);return;}
 let rows=[];try{rows=await rpc('session-roster',{id:S.project.id,session:S.session.id});}catch(e){toast(e.message);}
 show('Classroom session',`<p><strong>Student join link</strong></p><input type="text" id="join-link" readonly value="${esc(inviteLink())}" style="width:100%"><div class="button-row"><button data-action="copy-link">Copy link</button><button data-action="qr">Show QR code</button><button data-action="roster-csv">Export participation CSV</button></div><div id="session-qr"></div><div class="two-fields"><label class="field">Student access<select id="session-mode"><option value="edit" ${S.session.mode==='edit'?'selected':''}>Collaborative editing</option><option value="view" ${S.session.mode==='view'?'selected':''}>View only</option></select></label><label class="field">Timer minutes<input id="timer-minutes" type="number" min="1" max="180" value="10"></label></div><div class="button-row"><button data-action="session-mode">Update access</button><button data-action="session-lock">${S.session.locked?'Unlock editing':'Lock editing'}</button><button data-action="timer-start">Start timer</button><button data-action="timer-stop">Clear timer</button><button data-action="end-session" class="danger">End session & revoke link</button></div><h3>Participants (${rows.length})</h3><p class="hint">Names and reflections are self-reported. Contributions count successful map saves, not learning completion.</p><table><thead><tr><th>Participant / team</th><th>Saves</th><th>Reflection</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.name)}<br>${esc(r.team)}</td><td>${r.contributions}</td><td>${esc(r.reflection)}</td></tr>`).join('')}</tbody></table>`);S.roster=rows;
}
async function hostSession(){await save();if(S.dirty||!S.version||S.saving)return toast('Complete the website save before opening a classroom session.');try{const s=await rpc('session-create',{id:S.project.id});S.session=s;renderSession();startPolling();await classroom();}catch(e){toast(e.message);}}
async function settings(patch){try{const next=await rpc('session-settings',{id:S.project.id,session:S.session.id,...patch});S.session={...S.session,...next};renderSession();if(patch.active===false){S.session=null;clearInterval(pollTimer);renderSession();closeModal();toast('Session ended. The old student link is revoked.');}else classroom();}catch(e){toast(e.message);}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(poll,3500);}
async function poll(){
 if(!S.session||S.polling)return;S.polling=true;
 try{const d=await rpc('session-get',{room:S.session.room,...(participant?{member:S.member?.id,proof:S.member?.proof}:{})});const old=editable();S.session={...S.session,...d.session};
  if(old!==editable()){renderNodes();renderInspector();}
  if(d.version!==S.version&&!S.dirty&&!S.saving&&!S.gesture&&!document.activeElement?.isContentEditable){S.project=loadProject(d.data);S.version=d.version;S.rev++;lastAnalysis=-1;render();status('Live classroom · website version '+d.version);}
  renderSession();
 }catch(e){if(e.status===404){S.session.active=false;S.session.locked=true;render();renderSession();clearInterval(pollTimer);toast('This classroom session has ended. You can export your copy.');}else status('Classroom connection interrupted · device draft kept');}
 finally{S.polling=false;}
}
async function joinClass(){
 const room=new URLSearchParams(location.hash.slice(1)).get('room');if(!room||!/^[a-f0-9]{48}$/.test(room)){show('Join a systems mapping class','<p>A valid invitation link from your instructor is required.</p>');return;}
 try{const member=JSON.parse(sessionStorage.getItem('ml.systems.member.'+room)||'null');if(member){const d=await rpc('session-get',{room,member:member.id,proof:member.proof});S.member=member;S.project=loadProject(d.data);S.version=d.version;S.session={...d.session,room};S.rev++;lastAnalysis=-1;render();fit();renderSession();startPolling();status('Reconnected to classroom map');return;}}catch{}
 show('Join the systems map','<div class="join-card"><p>Enter your name and optional team. Your name and reflection will be visible to the instructor.</p><label class="field">Display name<input type="text" id="student-name" maxlength="80" autocomplete="name"></label><label class="field">Team<input type="text" id="student-team" maxlength="80"></label><button data-action="join-session" class="primary full">Join class</button></div>');S.joinRoom=room;
}
async function joinSubmit(){const name=$('#student-name').value.trim();if(!name)return toast('Enter a display name.');try{const d=await rpc('session-join',{room:S.joinRoom,name,team:$('#student-team').value.trim()});S.member={id:d.member,proof:d.proof};try{sessionStorage.setItem('ml.systems.member.'+S.joinRoom,JSON.stringify(S.member));}catch{}S.project=loadProject(d.data);S.version=d.version;S.session={...d.session,room:S.joinRoom};S.rev++;lastAnalysis=-1;S.dirty=false;render();fit();renderSession();closeModal();startPolling();status('Joined classroom map');}catch(e){toast(e.message);}}
async function reloadCloud(){
 if(S.dirty&&!confirm('Your unsynced draft stays in My Maps on this device. Reload the latest website version? Export JSON first if you want a separate backup.'))return;
 flushLocal();try{const d=await rpc(participant?'session-get':'get',participant?{room:S.session.room,member:S.member.id,proof:S.member.proof}:{id:S.project.id});
  // Preserve a conflicting source as a distinct device project before replacing it.
  if(S.dirty){const backup=copy(S.project);backup.id=uid();backup.title=(backup.title+' · conflict draft').slice(0,100);saveLocal(backup,0,true);}
  S.project=loadProject(d.data);S.version=d.version;S.dirty=false;S.conflict=false;S.rev++;lastAnalysis=-1;S.history=[];S.future=[];saveLocal(S.project,S.version,false);render();renderSession();toast('Website version loaded.');
 }catch(e){toast(e.message);}
}
const handlers={
 'toggle-left':()=>document.body.classList.toggle('left-collapsed'),'toggle-right':()=>document.body.classList.toggle('right-collapsed'),
 'mobile-left':()=>{document.body.classList.remove('mobile-right');document.body.classList.toggle('mobile-left');},'mobile-right':()=>{document.body.classList.remove('mobile-left');document.body.classList.toggle('mobile-right');},
 iceberg:()=>worksheet('iceberg'),behavior:()=>worksheet('behavior'),simulation:()=>worksheet('simulation'),actions:()=>worksheet('actions'),
 'clear-highlight':()=>{S.highlight=null;paintSelection();},
 delete:()=>transact(()=>{removeItems(S.project,[...S.selected]);S.selected.clear();}),
 duplicate:()=>{if(S.project.nodes.length+S.selected.size>LIMITS.nodes)return toast('Element limit reached.');transact(()=>S.selected=new Set(duplicate(S.project,[...S.selected])));},
 align:()=>transact(()=>{const list=S.project.nodes.filter(n=>S.selected.has(n.id)&&!n.locked);const top=Math.min(...list.map(n=>n.y));for(const n of list)n.y=top;}),
 'reverse-edge':()=>transact(()=>{const e=current();[e.from,e.to]=[e.to,e.from];}),
 'trace-up':()=>doTrace(1),'trace-down':()=>doTrace(-1),
 import:()=>$('#import-file').click(),classroom, 'host-session':hostSession,'join-session':joinSubmit,'reload-cloud':reloadCloud,
 'copy-link':async()=>{try{await navigator.clipboard.writeText(inviteLink());toast('Student link copied.');}catch{$('#join-link').select();toast('Copy the selected link.');}},
 qr:()=>{if(typeof window.QRCode!=='function')return toast('QR encoder is unavailable. Copy the student link.');const target=$('#session-qr');target.innerHTML='';target.classList.add('qr');target.setAttribute('aria-label','QR code for student join link');new window.QRCode(target,{text:inviteLink(),width:190,height:190,correctLevel:window.QRCode.CorrectLevel.M});},
 'session-mode':()=>settings({mode:$('#session-mode').value}), 'session-lock':()=>settings({locked:!S.session.locked}),
 'timer-start':()=>settings({minutes:clamp(Number($('#timer-minutes').value)||10,1,180)}),'timer-stop':()=>settings({minutes:0}),'end-session':()=>{if(confirm('End this session and revoke the student link?'))settings({active:false});},
 'student-reflect':()=>show('Classroom reflection','<p>What did your team learn about feedback, delays, or unintended consequences?</p><textarea id="student-reflection" maxlength="4000"></textarea><button data-action="submit-reflection" class="primary full">Submit reflection</button>'),
 'submit-reflection':async()=>{try{await rpc('session-reflect',{room:S.session.room,member:S.member.id,proof:S.member.proof,reflection:$('#student-reflection').value});toast('Reflection submitted.');closeModal();}catch(e){toast(e.message);}},
 'roster-csv':()=>download(safeName(S.project)+'-participation.csv',participantCSV(S.roster||[]),'text/csv;charset=utf-8'),
 'simulation-csv':()=>{const s=simulate(S.project);download(safeName(S.project)+'-stock-flow.csv',[['time',...s.stocks.map(n=>'"'+n.label.replace(/"/g,'""')+'"')].join(','),...s.rows.map(r=>[r.time,...s.stocks.map(n=>r[n.id])].join(','))].join('\r\n'),'text/csv');},
 'add-action':()=>{if(S.project.actions.length>=100)return;transact(()=>S.project.actions.push({id:uid(),text:'',owner:'',due:'',measure:'',status:'planned'}));drawActions();},
 history:async()=>{if(!S.version)return toast('Save this map to the website first.');try{const rows=await rpc('history',{id:S.project.id});S.revisions=rows;show('Website version history','<p>Restore a previous source as your next editable draft. The current website version remains until you save.</p>'+rows.map((r,i)=>`<div class="card">Version ${r.version} · ${esc(String(r.created_at).slice(0,16))} <button data-restore="${i}">Restore as draft</button></div>`).join(''));}catch(e){toast(e.message);}},
 help:()=>show('Systems Mapping Studio guide',`<p><strong>1. Frame.</strong> Define the focal issue and scope in Inspect. Use Guided for an eight-step process or Freeform to work in any order.</p><p><strong>2. Build.</strong> Click or drag a toolbox item. Click its text and type directly. Drag its header to move it. Select it and drag the gold corner to resize. Shift-click to select more than one; Shift-drag empty canvas to select a region. Right-drag or hold Space to pan. Use the wheel to zoom.</p><p><strong>3. Connect.</strong> Drag a gold connection dot to another element, or select Connect and click a cause, then an effect. Click an arrow to set its sign, confidence, evidence, and delay. A self-loop can be created by selecting the same node twice.</p><p><strong>4. Analyze.</strong> Feedback finds elementary directed causal loops. An even number of negative links is reinforcing; an odd number is balancing. Unknown signs yield uncertain loops. Stock / flow and information links are excluded. Review highlights missing evidence and highly connected elements. Connectivity is not a measure of intervention effectiveness.</p><p><strong>5. Test your thinking.</strong> Trace possible effects, mark leverage points, use the iceberg and behavior-over-time tools, and record actions and reflection. The stock / flow tool illustrates constant rates only.</p><p><strong>6. Save and share.</strong> Save creates a website project and enables website autosave. My Maps includes website projects and device recovery copies. Website authors share access through the existing instructor PIN. Start Classroom to invite students without the PIN, choose edit/view access, lock editing, set a timer, and collect reflections.</p><p><strong>7. Export.</strong> JSON retains the complete editable project. SVG and PNG capture the map. The self-contained HTML report includes the map, loops, evidence, action plan, and reflection; open it and choose Print / Save as PDF. CSV opens in Excel. Collaboration Canvas transfers retain layout and text.</p><p><strong>Shortcuts:</strong> V select · H pan · C connect · Delete remove · Ctrl/Cmd+D duplicate · Ctrl/Cmd+S save · Ctrl/Cmd+Z undo · Ctrl/Cmd+Shift+Z redo · Arrow keys nudge (Shift = 10px) · Escape close / clear selection. Undo is disabled during a classroom session to avoid replaying another person’s work.</p><p><strong>Limits:</strong> 250 elements, 600 relationships, 40 boundaries, 1.5 MB source. Loop search: 200 cycles, 60,000 traversal steps, up to 30 variables per loop; a warning appears when bounded. Classroom sync polls every 3.5 seconds and uses revision conflicts, not automatic concurrent text merging. Export your conflicting draft before reloading.</p>`)
};
function doTrace(sign){const n=current();if(!n)return;S.trace=trace(S.project,n.id,3,sign);S.highlight={nodes:[...new Set(S.trace.paths.flatMap(x=>x.nodes))],edges:[...new Set(S.trace.paths.flatMap(x=>x.edges))]};paintSelection();renderInspector();}
document.addEventListener('click',async e=>{
 const b=e.target.closest('button');if(!b||b.disabled)return;
 try{
  if(b.dataset.action){await handlers[b.dataset.action]?.();return;}
  if(b.dataset.add){addNode(b.dataset.add);return;}
  if(b.dataset.tool){setTool(b.dataset.tool);return;}
  if(b.dataset.tab){S.tab=b.dataset.tab;renderInspector();return;}
  if(b.dataset.mode){transact(()=>S.project.mode=b.dataset.mode);return;}
  if(b.dataset.loop!==undefined){S.highlight=getAnalysis().loops[Number(b.dataset.loop)];paintSelection();return;}
  if(b.dataset.selectNode){select(b.dataset.selectNode);S.tab='inspect';renderInspector();return;}
  if(b.dataset.export){await doExport(b.dataset.export);return;}
  if(b.dataset.openMap||b.dataset.copyMap){const id=b.dataset.openMap||b.dataset.copyMap,d=await getSource(id,b.dataset.source);if(b.dataset.copyMap){const p=copy(d.data);p.id=uid();p.title=(p.title+' · copy').slice(0,100);openProject(p,0,true);changed();}else openProject(d.data,d.version,d.dirty===true);closeModal();return;}
  if(b.dataset.archiveMap){if(!confirm('Archive this website map? Device copies remain in My Maps.'))return;await rpc('archive',{id:b.dataset.archiveMap});library();return;}
  if(b.dataset.removeLocal){if(confirm('Remove this device copy? Website versions are retained.')){deleteLocal(b.dataset.removeLocal);library();}return;}
  if(b.dataset.restore!==undefined){const item=S.revisions[Number(b.dataset.restore)];transact(()=>S.project=loadProject(item.data));closeModal();toast('Previous version restored as a draft.');return;}
  if(b.dataset.removeAction){transact(()=>S.project.actions=S.project.actions.filter(x=>x.id!==b.dataset.removeAction));drawActions();return;}
 }catch(error){toast(error.message);}
});
$('#new-map').onclick=reset;$('#save-map').onclick=save;$('#open-library').onclick=library;$('#export-menu').onclick=exportMenu;$('#classroom').onclick=classroom;
$('#close-modal').onclick=closeModal;$('#modal-backdrop').addEventListener('click',e=>{if(e.target===$('#modal-backdrop'))closeModal();});
$('#first-node').onclick=()=>addNode('variable');$('#relation-tool').onclick=()=>setTool('connect');$('#group-tool').onclick=()=>{if(S.project.groups.length>=LIMITS.groups)return toast('Boundary limit reached.');transact(()=>{const c=center(),g=group(c.x-170,c.y-100);S.project.groups.push(g);S.selected=new Set([g.id]);});};
$('#guide-next').onclick=()=>{transact(()=>S.project.stage=clamp(S.project.stage+1,0,7));const stage=S.project.stage;if(stage===3){S.tab='loops';renderInspector();}if(stage===6){S.tab='review';renderInspector();}if(stage===7)worksheet('actions');};$('#guide-prev').onclick=()=>transact(()=>S.project.stage=clamp(S.project.stage-1,0,7));
$('#load-template').onclick=()=>{const key=$('#template').value;if(!key)return toast('Choose a template.');if(S.dirty||S.project.nodes.length){flushLocal();if(!confirm('Load a fresh template? Your current map is kept in My Maps on this device.'))return;}openProject(template(key),0,true);changed();};
$('#project-title').addEventListener('change',e=>{if(!editable()||participant)return;snapshot();S.project.title=e.target.value.trim().slice(0,100)||'Untitled System Map';changed();});
$('#present').onclick=()=>{document.body.classList.toggle('presenting');$('#present').textContent=document.body.classList.contains('presenting')?'Exit presentation':'Present';setTimeout(fit,0);};
$('#fit').onclick=fit;$('#zoom-in').onclick=()=>zoom(1.15);$('#zoom-out').onclick=()=>zoom(1/1.15);$('#toggle-grid').onclick=()=>{$('#viewport').classList.toggle('no-grid');$('#toggle-grid').classList.toggle('enabled');};
function undo(redo=false){if(!editable()||S.session)return;const from=redo?S.future:S.history,to=redo?S.history:S.future;if(!from.length)return;to.push(copy(S.project));S.project=from.pop();S.selected.clear();S.highlight=null;changed();render();}
$('#undo').onclick=()=>undo();$('#redo').onclick=()=>undo(true);
