document.addEventListener('dragstart',e=>{const el=e.target.closest('[data-add]');if(el)e.dataTransfer.setData('application/x-mayne-system',el.dataset.add);});
$('#viewport').addEventListener('dragover',e=>{if([...e.dataTransfer.types].includes('application/x-mayne-system'))e.preventDefault();});
$('#viewport').addEventListener('drop',e=>{const type=e.dataTransfer.getData('application/x-mayne-system');if(TYPES[type]){e.preventDefault();addNode(type,worldPoint(e));}});
function targetForField(el){const key=el.dataset.field;if(key.startsWith('iceberg.')||key.startsWith('behavior.')){const [a,b]=key.split('.');return [S.project[a],b];}if(key.startsWith('action.'))return [S.project.actions.find(a=>a.id===el.closest('[data-action-id]')?.dataset.actionId),key.slice(7)];if(el.closest('#inspector')&&current()&&S.selected.size===1)return [current(),key];return [S.project,key];}
document.addEventListener('focusin',e=>{if(e.target.matches('[data-field],.node-label')&&editable()){focusSnapshot=copy(S.project);focusSnapshot._target=e.target;}});
document.addEventListener('input',e=>{
 const el=e.target;if(!editable())return;
 if(el.matches('.node-label')){const n=S.project.nodes.find(n=>n.id===el.closest('[data-id]').dataset.id);if(!n||n.locked)return;n.label=el.textContent.slice(0,200);changed();renderEdges();return;}
 if(!el.matches('[data-field]'))return;const [target,key]=targetForField(el);if(!target)return;
 let value=el.type==='checkbox'?el.checked:el.type==='number'?Number(el.value):el.value;if(el.type==='number'&&!Number.isFinite(value))return;
 if(['w','h'].includes(key))value=clamp(value,key==='w'?90:60,3000);if(key==='bend')value=clamp(value,-800,800);if(key==='label')value=String(value).slice(0,200);
 target[key]=value;changed();if(el.dataset.field==='behavior.points'||el.dataset.field==='behavior.label')drawBehavior();if(el.closest('#inspector')){const n=current(),dom=n&&$(`[data-id="${n.id}"]`);if(dom){dom.style.width=n.w+'px';dom.style.height=n.h+'px';dom.style.background=n.color;if(key==='label')dom.querySelector('.node-label,.group-label').textContent=n.label;}renderEdges();renderMinimap();}
});
document.addEventListener('change',e=>{if(e.target.matches('[data-field]')){if(e.target.tagName==='SELECT'||e.target.type==='checkbox')e.target.dispatchEvent(new Event('input',{bubbles:true}));if(e.target.closest('#inspector')&&['type','kind','locked'].includes(e.target.dataset.field)){renderNodes();renderInspector();}}});
document.addEventListener('focusout',e=>{
 if(focusSnapshot?._target===e.target){const old=focusSnapshot;delete old._target;focusSnapshot=null;if(JSON.stringify(old)!==JSON.stringify(S.project)){S.history.push(old);if(S.history.length>45)S.history.shift();S.future=[];updateUndo();}}
});
