viewport.addEventListener('pointerdown',e=>{
 if(e.button!==0&&e.button!==2)return;const el=e.target.closest('[data-id]'),hit=e.target.closest('[data-edge]'),p=worldPoint(e),pan=e.button===2||S.space||S.tool==='pan';
 if(pan){e.preventDefault();S.gesture={type:'pan',clientX:e.clientX,clientY:e.clientY,x:S.view.x,y:S.view.y};viewport.classList.add('panning');return;}
 if(hit){select(hit.dataset.edge,e.shiftKey);return;}
 if(el){const id=el.dataset.id,n=S.project.nodes.find(n=>n.id===id)||S.project.groups.find(n=>n.id===id);if(!n)return;
  if((S.tool==='connect'||e.target.closest('.port'))&&S.project.nodes.includes(n)){e.preventDefault();if(!editable())return;if(S.tool==='connect'){if(S.connectFrom)connect(S.connectFrom,id);else{S.connectFrom=id;select(id);toast('Now click the effect.');}}else{S.gesture={type:'connect',from:id,start:p};}return;}
  if(!S.selected.has(id)||e.shiftKey)select(id,e.shiftKey);
  if(e.target.closest('.node-label'))return;
  if(!editable()||n.locked)return;
  if(e.target.closest('.resize-handle')){e.preventDefault();snapshot();S.gesture={type:'resize',id,start:p,w:n.w,h:n.h};return;}
  if(e.target.closest('.node-header,.group-label')){e.preventDefault();snapshot();const ids=new Set(S.selected);if(S.project.groups.includes(n))for(const child of S.project.nodes)if(child.group===id)ids.add(child.id);const items=[...S.project.nodes,...S.project.groups].filter(x=>ids.has(x.id)&&!x.locked);S.gesture={type:'move',start:p,items:items.map(x=>({id:x.id,x:x.x,y:x.y}))};return;}
 }else{select(null);if(e.shiftKey){S.gesture={type:'lasso',start:p};const div=document.createElement('div');div.className='lasso';div.id='selection-lasso';$('#world').append(div);} }
});
window.addEventListener('pointermove',e=>{
 const g=S.gesture;if(!g)return;
 if(g.type==='pan'){S.view.x=g.x+e.clientX-g.clientX;S.view.y=g.y+e.clientY-g.clientY;view();return;}
 const p=worldPoint(e),dx=p.x-g.start.x,dy=p.y-g.start.y;
 if(g.type==='connect'){const path=$('#connect-preview');path.hidden=false;path.setAttribute('d',`M${g.start.x} ${g.start.y}L${p.x} ${p.y}`);return;}
 if(g.type==='lasso'){const box=$('#selection-lasso');Object.assign(box.style,{left:Math.min(p.x,g.start.x)+'px',top:Math.min(p.y,g.start.y)+'px',width:Math.abs(dx)+'px',height:Math.abs(dy)+'px'});return;}
 if(!editable())return;
 const snap=x=>$('#viewport').classList.contains('no-grid')?x:Math.round(x/10)*10;
 if(g.type==='move')for(const initial of g.items){const n=S.project.nodes.find(n=>n.id===initial.id)||S.project.groups.find(n=>n.id===initial.id);n.x=clamp(snap(initial.x+dx),-19000,19000);n.y=clamp(snap(initial.y+dy),-19000,19000);const el=$(`[data-id="${n.id}"]`);el.style.left=n.x+'px';el.style.top=n.y+'px';}
 if(g.type==='resize'){const n=S.project.nodes.find(n=>n.id===g.id)||S.project.groups.find(n=>n.id===g.id);n.w=clamp(snap(g.w+dx),90,3000);n.h=clamp(snap(g.h+dy),60,3000);const el=$(`[data-id="${n.id}"]`);el.style.width=n.w+'px';el.style.height=n.h+'px';}
 renderEdges();renderMinimap();
});
window.addEventListener('pointerup',e=>{
 const g=S.gesture;if(!g)return;S.gesture=null;viewport.classList.remove('panning');$('#connect-preview').hidden=true;
 if(g.type==='connect'){const target=e.target.closest?.('.map-node')||document.elementFromPoint?.(e.clientX,e.clientY)?.closest('.map-node');if(target)connect(g.from,target.dataset.id);}
 if(g.type==='move'||g.type==='resize'){changed();renderInspector();}
 if(g.type==='lasso'){const p=worldPoint(e),x=Math.min(p.x,g.start.x),y=Math.min(p.y,g.start.y),right=Math.max(p.x,g.start.x),bottom=Math.max(p.y,g.start.y);S.selected=new Set(S.project.nodes.filter(n=>n.x>=x&&n.y>=y&&n.x+n.w<=right&&n.y+n.h<=bottom).map(n=>n.id));$('#selection-lasso')?.remove();paintSelection();renderInspector();}
});
window.addEventListener('pointercancel',()=>{if(S.gesture?.type==='move'||S.gesture?.type==='resize'){S.project=S.history.pop()||S.project;render();}S.gesture=null;$('#connect-preview').hidden=true;viewport.classList.remove('panning');$('#selection-lasso')?.remove();});
$('#map-minimap').addEventListener('click',e=>{const b=bounds(S.project),r=$('#map-minimap').getBoundingClientRect(),s=viewportSize();S.view.x=s.w/2-(b.x+(e.clientX-r.left)/r.width*b.w)*S.view.z;S.view.y=s.h/2-(b.y+(e.clientY-r.top)/r.height*b.h)*S.view.z;view();});
document.addEventListener('keydown',e=>{
 const typing=e.target.matches('input,textarea,select,[contenteditable=true]'),mod=e.ctrlKey||e.metaKey;
 if(e.key==='Escape'){closeModal();S.connectFrom=null;S.highlight=null;select(null);if(document.body.classList.contains('presenting'))$('#present').click();return;}
 if(e.key==='Tab'&&!$('#modal-backdrop').hidden){const focusables=[$('#close-modal'),...$('#modal-content').querySelectorAll('button,input,textarea,select,a[href]')].filter(x=>!x.disabled);const i=focusables.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();focusables.at(-1)?.focus();}else if(!e.shiftKey&&i===focusables.length-1){e.preventDefault();focusables[0].focus();}return;}
 if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();document.activeElement?.blur?.();save();return;}
 if(typing)return;
 if(e.code==='Space'){e.preventDefault();S.space=true;return;}
 if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}
 if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}
 if(mod&&e.key.toLowerCase()==='d'){e.preventDefault();handlers.duplicate();return;}
 if(e.key==='Delete'||e.key==='Backspace'){if(S.selected.size){e.preventDefault();handlers.delete();}return;}
 if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key)&&S.selected.size){e.preventDefault();transact(()=>{const d=e.shiftKey?10:1;for(const n of [...S.project.nodes,...S.project.groups].filter(n=>S.selected.has(n.id)&&!n.locked)){n.x=clamp(n.x+(e.key==='ArrowLeft'?-d:e.key==='ArrowRight'?d:0),-19000,19000);n.y=clamp(n.y+(e.key==='ArrowUp'?-d:e.key==='ArrowDown'?d:0),-19000,19000);}});return;}
 if(!mod){if(e.key.toLowerCase()==='v')setTool('select');if(e.key.toLowerCase()==='h')setTool('pan');if(e.key.toLowerCase()==='c')setTool('connect');}
});
document.addEventListener('keyup',e=>{if(e.code==='Space')S.space=false;});window.addEventListener('blur',()=>{S.space=false;});
$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>LIMITS.bytes)throw Error('Import limit is 1.5 MB.');const data=JSON.parse(await file.text());let p=data.format==='mayne-canvas-v1'?fromCollaboration(data):loadProject(data);p.id=uid();p.title=p.title.slice(0,100);openProject(p,0,true);changed();closeModal();toast('Project imported as a new editable copy.');}catch(error){toast(error.message);}finally{e.target.value='';}});
window.addEventListener('beforeunload',e=>{flushLocal();if(S.dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('resize',view);setInterval(updateTimer,1000);
if(participant){document.body.classList.add('participant');for(const id of ['new-map','open-library','load-template','group-tool'])$('#'+id).classList.add('owner-only');$('#project-title').readOnly=true;}
render();view();if(participant)joinClass();
